// @contract: renderUserProfile(user: User) => JSX.Element
// @step: [验证用户] 检查 user 对象是否有效
// @step: [渲染头像] 渲染用户头像组件
// @step: [渲染信息] 渲染用户名、邮箱等信息
// @step: [返回] 返回完整的 JSX 元素
// @boundary: 当 user 为 null 时，返回空状态组件

output.content:
function renderUserProfile(user: User): JSX.Element {
  if (!user) {
    return <div className="empty-state">No user data available</div>;
  }

  return (
    <div className="user-profile">
      <div className="avatar-section">
        {user.avatar && <img src={user.avatar} alt={user.name} className="avatar" />}
        {!user.avatar && <div className="avatar-placeholder">No Avatar</div>}
      </div>
      <div className="info-section">
        <h2 className="user-name">{user.name}</h2>
        <p className="user-email">{user.email}</p>
      </div>
    </div>
  );
}
// @end
